export const DOMAINS = [
  { key: "transformation", label: "Digital Transformation with Google Cloud", weightPct: 10 },
  { key: "data", label: "Innovating with Data & Google Cloud", weightPct: 30 },
  { key: "infrastructure", label: "Infrastructure & Application Modernization", weightPct: 30 },
  { key: "security", label: "Security & Operations", weightPct: 30 },
];

const questions = [
  // ── DIGITAL TRANSFORMATION WITH GOOGLE CLOUD ────────────────────────────────
  { id: 1, domain: "transformation", question: "A traditional retailer currently buys and maintains its own servers, which sit mostly idle except during the December holiday rush. Which cloud computing benefit most directly solves this problem?", options: ["Data sovereignty controls", "Elastic, pay-as-you-go scaling of compute resources", "A dedicated on-premises support contract", "Fixed long-term hardware leasing"], answer: 1, explanation: "Cloud elasticity lets you scale resources up for peak demand and back down afterward, so you only pay for what you use instead of over-provisioning hardware year-round." },
  { id: 2, domain: "transformation", question: "Which statement best describes the shift from CapEx to OpEx that cloud computing enables?", options: ["Cloud computing eliminates all business costs entirely", "Instead of large upfront investments in hardware, organizations pay ongoing operational costs based on usage", "Capital expenditure only applies to on-premises networking equipment", "OpEx is only relevant to Google Cloud, not other providers"], answer: 1, explanation: "On-premises infrastructure requires large upfront capital expenditure (CapEx); cloud computing converts this into predictable operational expenditure (OpEx) paid as resources are consumed." },
  { id: 3, domain: "transformation", question: "A hospital network is deciding whether to move its patient records systems to the cloud. Which is a genuine business driver of digital transformation in this scenario?", options: ["The desire to reduce the number of doctors employed", "The need to improve agility, reduce IT overhead, and enable data-driven insights across facilities", "A legal requirement to only use paper records", "The elimination of the need for any data security measures"], answer: 1, explanation: "Digital transformation is typically driven by the need for greater agility, lower operational overhead, and better use of data for decision-making, not by cutting clinical staff or removing security needs." },
  { id: 4, domain: "transformation", question: "What does Google Cloud's global network of regions and zones primarily provide to customers?", options: ["A single physical data center that serves the entire world", "Low latency, high availability, and disaster recovery options by distributing resources geographically", "A guarantee that no outages will ever occur", "Free data transfer between all clouds worldwide"], answer: 1, explanation: "Regions and zones let customers place workloads close to their users for lower latency and replicate across locations for redundancy and disaster recovery." },
  { id: 5, domain: "transformation", question: "A sustainability officer wants to choose a cloud provider that aligns with the company's carbon-reduction goals. Which Google Cloud claim is most relevant to this decision?", options: ["Google Cloud offers the lowest price in every region", "Google has matched 100% of its annual electricity consumption with renewable energy purchases since 2017 and aims to run entirely on carbon-free energy", "Google Cloud does not track energy usage", "Sustainability is not a factor Google considers in data center design"], answer: 1, explanation: "Google has published matching 100% of its annual global electricity use with renewable energy since 2017, and has a goal of operating on 24/7 carbon-free energy, a genuine differentiator for sustainability-focused customers." },
  { id: 6, domain: "transformation", question: "Which of the following best reflects Google's contribution to open-source software relevant to cloud customers?", options: ["Google keeps all of its internal infrastructure tools proprietary", "Google originated and open-sourced projects such as Kubernetes and TensorFlow, reducing vendor lock-in for customers", "Open source is discouraged within Google Cloud's ecosystem", "Kubernetes is a Microsoft product adopted by Google"], answer: 1, explanation: "Google open-sourced Kubernetes (container orchestration) and TensorFlow (machine learning), both now industry standards, which helps customers avoid being locked into a single vendor's proprietary tools." },
  { id: 7, domain: "transformation", question: "A business leader wants to justify a cloud migration to the board using a Total Cost of Ownership (TCO) argument. Which factor should be included in that analysis?", options: ["Only the sticker price of virtual machines", "Hardware purchase costs, maintenance, power, cooling, staffing, and opportunity cost of on-premises infrastructure compared to cloud alternatives", "The number of company logos using the cloud provider", "The color scheme of the vendor's website"], answer: 1, explanation: "TCO analysis compares the full cost of running infrastructure on-premises (hardware, power, cooling, staffing, maintenance) against the cloud alternative, not just a single line-item price." },
  { id: 8, domain: "transformation", question: "Why might a startup choose Google Cloud over building its own data center from day one?", options: ["Because building a data center is always cheaper for a new company", "Because cloud lets the startup access enterprise-grade infrastructure immediately without large upfront capital investment", "Because startups are legally required to use cloud providers", "Because on-premises infrastructure is more scalable than cloud"], answer: 1, explanation: "Cloud computing removes the need for large upfront capital investment, letting a startup access global, enterprise-grade infrastructure on day one and scale as it grows." },
  { id: 9, domain: "transformation", question: "An organization currently forecasts server capacity a year in advance and often either over-buys (wasting money) or under-buys (causing outages). Which cloud value proposition addresses this specific pain point?", options: ["Vendor lock-in", "On-demand provisioning that scales resources to match actual demand", "A single annual invoice with no itemization", "Mandatory multi-year hardware contracts"], answer: 1, explanation: "On-demand, elastic provisioning removes the need to guess future capacity months in advance, letting resources scale automatically to match real-time demand." },
  { id: 10, domain: "transformation", question: "Which of these is a core part of Google Cloud's stated value proposition to enterprise customers?", options: ["Requiring customers to migrate everything to Google Cloud within 30 days", "Combining global scale infrastructure, strong security, open-source leadership, and built-in AI/ML capabilities", "Offering only infrastructure with no data or AI services", "Restricting customers to a single supported programming language"], answer: 1, explanation: "Google Cloud's value proposition centers on global infrastructure scale, security, openness (open source, multi-cloud), and deep investment in data and AI/ML capabilities." },

  // ── INNOVATING WITH DATA & GOOGLE CLOUD ─────────────────────────────────────
  { id: 11, domain: "data", question: "Which Google Cloud database service is purpose-built for horizontally scalable, globally consistent relational data with strong transactional guarantees?", options: ["Cloud SQL", "Cloud Spanner", "Firestore", "Bigtable"], answer: 1, explanation: "Cloud Spanner combines relational structure with strong consistency and horizontal scalability across regions, which traditional relational databases like Cloud SQL cannot offer at global scale." },
  { id: 12, domain: "data", question: "A mobile game studio needs a NoSQL database that automatically syncs data in real time across users' devices and scales for a global mobile app. Which service fits best?", options: ["Cloud SQL", "Firestore", "BigQuery", "Cloud Spanner"], answer: 1, explanation: "Firestore is a NoSQL document database designed for mobile and web apps, offering real-time synchronization and offline support across devices." },
  { id: 13, domain: "data", question: "An ad-tech company ingests billions of time-series events per day and needs extremely low-latency reads and writes at massive scale, with a wide-column NoSQL model. Which database should they choose?", options: ["Cloud Bigtable", "Cloud SQL", "Firestore", "Looker"], answer: 0, explanation: "Bigtable is a wide-column NoSQL database designed for very high-throughput, low-latency workloads such as time-series and IoT data, at petabyte scale." },
  { id: 14, domain: "data", question: "A small e-commerce business wants a fully managed relational database compatible with MySQL to run its existing application with minimal code changes. Which service is the best fit?", options: ["Cloud Spanner", "Cloud SQL", "Bigtable", "BigQuery"], answer: 1, explanation: "Cloud SQL is a fully managed relational database service supporting MySQL, PostgreSQL, and SQL Server, ideal for lift-and-shift of traditional relational workloads." },
  { id: 15, domain: "data", question: "What is BigQuery primarily used for?", options: ["Serving low-latency transactional application requests", "Running serverless, highly scalable SQL analytics over large datasets", "Hosting virtual machines", "Managing IAM permissions"], answer: 1, explanation: "BigQuery is Google Cloud's serverless data warehouse for running fast SQL analytics over massive datasets, not for transactional (OLTP) application workloads." },
  { id: 16, domain: "data", question: "A finance team wants to run ad hoc SQL queries across years of transaction history without managing any servers or clusters. Which product should they use?", options: ["Compute Engine", "BigQuery", "Cloud SQL", "Bigtable"], answer: 1, explanation: "BigQuery is serverless, meaning the finance team can query massive datasets with standard SQL without provisioning or managing any infrastructure." },
  { id: 17, domain: "data", question: "Which Google Cloud service is a fully managed, real-time messaging service used to decouple data producers and consumers in event-driven pipelines?", options: ["Pub/Sub", "Dataflow", "Dataproc", "Data Fusion"], answer: 0, explanation: "Pub/Sub is a fully managed asynchronous messaging service that ingests and delivers event streams between producers and consumers reliably at scale." },
  { id: 18, domain: "data", question: "A company needs to process both streaming and batch data using the same programming model, ideally with autoscaling and no cluster management. Which service fits?", options: ["Dataproc", "Dataflow", "Cloud SQL", "Looker"], answer: 1, explanation: "Dataflow is a fully managed service (based on Apache Beam) for unified batch and stream data processing, with autoscaling and no cluster management required." },
  { id: 19, domain: "data", question: "An organization has an existing investment in Apache Spark and Hadoop jobs and wants to migrate them to Google Cloud with minimal rewrite. Which service should they use?", options: ["Dataproc", "BigQuery", "Firestore", "Pub/Sub"], answer: 0, explanation: "Dataproc is a managed Spark and Hadoop service, making it the natural choice for migrating existing Spark/Hadoop workloads to Google Cloud with minimal changes." },
  { id: 20, domain: "data", question: "Which service provides a graphical, low-code interface for building ETL/ELT data integration pipelines, aimed at users who prefer visual pipeline design over writing code?", options: ["Cloud Data Fusion", "Dataflow", "Cloud Composer", "Bigtable"], answer: 0, explanation: "Cloud Data Fusion offers a visual, drag-and-drop interface for building and managing data integration pipelines, making it accessible to less code-centric users." },
  { id: 21, domain: "data", question: "What best describes the \"data-to-AI lifecycle\" concept that Google Cloud promotes?", options: ["Data is collected once and never used again", "A continuous process of ingesting, storing, and processing data, then using it to train and deploy AI/ML models that generate new insights", "A lifecycle where AI models never require data updates", "A process exclusive to unstructured video data"], answer: 1, explanation: "The data-to-AI lifecycle describes the continuous flow from data ingestion and storage through analytics and finally into AI/ML model training and deployment, generating insights that feed back into the business." },
  { id: 22, domain: "data", question: "A retail company wants to build a custom machine learning model to predict customer churn, and its data scientists want a unified platform for the entire ML lifecycle (data prep, training, deployment, monitoring). Which product should they use?", options: ["Vertex AI", "Vision AI", "Looker", "Cloud SQL"], answer: 0, explanation: "Vertex AI is Google Cloud's unified machine learning platform covering the full ML lifecycle, from data preparation and training to deployment and monitoring of models." },
  { id: 23, domain: "data", question: "A company wants to automatically extract text and detect objects in scanned documents and photos without training its own machine learning model. Which type of Google Cloud offering is appropriate?", options: ["A pre-trained API such as Vision AI", "A custom-built Compute Engine cluster", "Cloud Spanner", "A manually coded neural network on-premises"], answer: 0, explanation: "Pre-trained APIs like Vision AI let developers add capabilities such as image labeling, OCR, and object detection without building or training their own ML models." },
  { id: 24, domain: "data", question: "Which Google Cloud API would a developer use to analyze the sentiment and extract entities from customer reviews written in free-form text, without building a custom model?", options: ["Vision AI", "Natural Language AI", "Bigtable", "Dataproc"], answer: 1, explanation: "Natural Language AI is a pre-trained API for analyzing text, including sentiment analysis, entity extraction, and syntax analysis, without requiring custom model training." },
  { id: 25, domain: "data", question: "What is Gemini, in the context of Google Cloud's AI offerings?", options: ["A relational database engine", "Google's family of multimodal generative AI models that can understand and generate text, images, code, and more", "A networking protocol for VPNs", "A billing and cost management tool"], answer: 1, explanation: "Gemini is Google's family of multimodal large language models capable of processing and generating text, images, audio, and code, available through Vertex AI and other Google products." },
  { id: 26, domain: "data", question: "A business analyst needs to build interactive dashboards and explore trusted, governed metrics that multiple teams across the company can consistently rely on. Which tool is designed for this?", options: ["Looker", "Pub/Sub", "Cloud Storage", "Compute Engine"], answer: 0, explanation: "Looker is Google Cloud's business intelligence platform for building governed data models, dashboards, and reports that ensure consistent metrics across an organization." },
  { id: 27, domain: "data", question: "A company wants near-real-time fraud detection that reacts to each transaction as it happens, rather than analyzing data in daily batches. Which architecture pattern is most appropriate?", options: ["Batch-load transactions once a day into a spreadsheet", "Stream transaction events through Pub/Sub into Dataflow for real-time processing and scoring", "Store transactions only in Cloud Storage archive tier", "Manually review each transaction in Looker the next morning"], answer: 1, explanation: "Streaming architectures using Pub/Sub for ingestion and Dataflow for real-time processing allow systems to detect and react to events like fraud within seconds, unlike batch processing." },
  { id: 28, domain: "data", question: "Which statement correctly distinguishes structured from unstructured data?", options: ["Structured data has no defined schema, while unstructured data always fits neatly into rows and columns", "Structured data fits a predefined schema like rows and columns (e.g., a sales database), while unstructured data (e.g., images, video, free text) does not have a fixed format", "All data in BigQuery is unstructured", "Unstructured data cannot be analyzed with AI"], answer: 1, explanation: "Structured data conforms to a predefined schema (tables, rows, columns), while unstructured data such as images, audio, or free text lacks a fixed structure and often requires AI/ML tools to extract insights." },
  { id: 29, domain: "data", question: "A logistics company wants to combine transactional order data with real-time GPS tracking to build a live dashboard for its operations team. Which combination of services best supports this use case?", options: ["Cloud SQL only, refreshed once a month", "Pub/Sub to ingest GPS events, Dataflow to process them, BigQuery to store and analyze, and Looker to visualize", "A single spreadsheet updated manually", "Bigtable used purely as a static file archive"], answer: 1, explanation: "This pipeline pattern, ingest with Pub/Sub, process with Dataflow, store/analyze in BigQuery, and visualize in Looker, is a standard Google Cloud architecture for real-time analytics dashboards." },
  { id: 30, domain: "data", question: "Why might an organization choose Cloud Spanner over Cloud SQL for a new global financial application?", options: ["Cloud Spanner is cheaper for all workloads regardless of scale", "Cloud Spanner offers horizontal scalability with strong consistency across regions, which Cloud SQL cannot provide at that scale", "Cloud Spanner only supports NoSQL queries", "Cloud SQL scales infinitely across regions by default"], answer: 1, explanation: "Cloud SQL scales vertically and is typically regional, while Cloud Spanner is designed to scale horizontally across regions while maintaining strong relational consistency, which suits large global financial systems." },
  { id: 31, domain: "data", question: "What is a key advantage of BigQuery's separation of storage and compute?", options: ["It requires customers to manually provision servers before running any query", "It allows you to scale query processing power independently of the amount of data stored, and pay only for what you use", "It means BigQuery cannot store more than a few gigabytes of data", "It eliminates the need for SQL knowledge"], answer: 1, explanation: "Because BigQuery separates storage and compute, customers can store massive datasets cheaply and only pay for the compute needed for the specific queries they run, without provisioning fixed clusters." },
  { id: 32, domain: "data", question: "A marketing team wants to try generative AI to automatically draft email campaign copy based on prior successful campaigns. Which capability are they using?", options: ["A traditional relational database query", "Generative AI, using a large language model to create new text content", "Cloud Bigtable indexing", "A manual data entry process"], answer: 1, explanation: "Generating new email copy from patterns in past campaigns is a generative AI use case, typically powered by a large language model such as Gemini through Vertex AI." },
  { id: 33, domain: "data", question: "Which of these is an example of a batch data processing use case, as opposed to streaming?", options: ["Detecting credit card fraud within milliseconds of a transaction", "Generating a nightly summary report of the previous day's total sales", "Live-updating a stock ticker every second", "Real-time chat message delivery"], answer: 1, explanation: "Batch processing handles data in large, scheduled chunks, such as a nightly sales report, whereas streaming processes data continuously as it arrives, such as fraud detection or live tickers." },
  { id: 34, domain: "data", question: "A company's data science team wants to deploy a trained model so that other applications can send it data and receive predictions via an API call. What is this deployment pattern commonly called in Vertex AI?", options: ["Data warehousing", "Model serving / online prediction endpoint", "Batch data ingestion", "Identity federation"], answer: 1, explanation: "Deploying a trained model behind an API so applications can request real-time predictions is known as online prediction (model serving), a core feature of Vertex AI." },
  { id: 35, domain: "data", question: "Which statement about Google's pre-trained AI APIs (such as Vision AI, Natural Language AI, and Translation AI) is accurate?", options: ["They require the customer to supply millions of labeled training examples before first use", "They provide ready-to-use AI capabilities via API calls, without the customer needing to build or train a model", "They can only be used with data stored in Cloud Spanner", "They are exclusively for internal Google use and unavailable to customers"], answer: 1, explanation: "Pre-trained APIs are ready to use out of the box, letting developers add capabilities like image recognition or translation via a simple API call, without training custom models." },
  { id: 36, domain: "data", question: "What is the primary purpose of a data warehouse like BigQuery, compared to an operational (transactional) database?", options: ["To process a high volume of small, individual transactions like ATM withdrawals", "To aggregate and analyze large volumes of historical data for business intelligence and reporting", "To serve as the only database an application ever needs", "To store website session cookies"], answer: 1, explanation: "Data warehouses are optimized for large-scale analytical queries over historical data (OLAP), while operational databases like Cloud SQL handle many small transactional reads/writes (OLTP)." },
  { id: 37, domain: "data", question: "An organization wants a fully managed way to orchestrate and schedule complex multi-step data workflows (e.g., \"run job A, then B, then C\") across various Google Cloud data services. Which product is designed for this?", options: ["Cloud Composer", "Cloud Bigtable", "Firestore", "Vision AI"], answer: 0, explanation: "Cloud Composer is a managed workflow orchestration service (based on Apache Airflow) used to author, schedule, and monitor pipelines across multiple data processing steps and services." },
  { id: 38, domain: "data", question: "A company is deciding between Firestore and Bigtable for a new application storing user profiles for a consumer mobile app with moderate traffic. Which factor most favors Firestore?", options: ["The need to ingest petabytes of IoT sensor data per day", "The need for real-time sync, offline support, and simple document-based queries for a mobile/web app", "The need for the lowest possible latency at massive analytical scale", "The requirement to run raw Hadoop MapReduce jobs"], answer: 1, explanation: "Firestore is optimized for mobile and web application patterns, real-time sync, offline support, and flexible document queries, while Bigtable targets massive-scale, high-throughput analytical or time-series workloads." },

  // ── INFRASTRUCTURE & APPLICATION MODERNIZATION ──────────────────────────────
  { id: 39, domain: "infrastructure", question: "A team wants full control over the operating system and needs to install custom software with specific kernel-level configurations. Which compute option should they choose?", options: ["Cloud Functions", "Compute Engine", "Cloud Run", "App Engine standard environment"], answer: 1, explanation: "Compute Engine provides customizable virtual machines with full control over the OS and configuration, unlike the more managed/serverless options." },
  { id: 40, domain: "infrastructure", question: "A developer has a small, stateless piece of code that should run only when triggered by an event (e.g., a file upload) and should require zero server management. Which service is the best fit?", options: ["Compute Engine", "Google Kubernetes Engine", "Cloud Functions", "Cloud Interconnect"], answer: 2, explanation: "Cloud Functions is a serverless, event-driven compute service ideal for small, single-purpose pieces of code triggered by events, with no infrastructure to manage." },
  { id: 41, domain: "infrastructure", question: "A team has containerized microservices and wants fine-grained control over orchestration, scaling policies, and networking between many interdependent services. Which compute platform is designed for this?", options: ["Google Kubernetes Engine (GKE)", "Cloud Functions", "App Engine standard", "Cloud Storage"], answer: 0, explanation: "GKE is a managed Kubernetes service designed for orchestrating complex, containerized microservice architectures with fine-grained control over scaling, networking, and deployment." },
  { id: 42, domain: "infrastructure", question: "A startup wants to deploy a containerized web application, have it automatically scale to zero when there's no traffic, and avoid managing any servers or clusters. Which service is the best match?", options: ["Compute Engine", "Cloud Run", "Google Kubernetes Engine", "Cloud Interconnect"], answer: 1, explanation: "Cloud Run is a fully managed serverless platform for running containers that automatically scales to zero when idle, without requiring cluster management like GKE." },
  { id: 43, domain: "infrastructure", question: "What is a defining characteristic of App Engine's standard environment?", options: ["It requires customers to manage their own virtual machines and patch the OS", "It is a fully managed platform-as-a-service for deploying application code directly, with the platform handling scaling and infrastructure", "It only supports running raw Kubernetes clusters", "It cannot scale automatically"], answer: 1, explanation: "App Engine standard environment is a platform-as-a-service (PaaS): developers deploy code and the platform manages the underlying infrastructure and automatic scaling." },
  { id: 44, domain: "infrastructure", question: "A company must decide between Cloud Run and Google Kubernetes Engine (GKE) for a new containerized service. Which factor would justify choosing GKE instead of Cloud Run?", options: ["The team wants zero infrastructure management and only needs simple, independent services", "The team needs complex multi-container pod configurations, custom networking, and fine-grained cluster control", "The team wants to deploy without ever thinking about containers", "The workload never needs to scale"], answer: 1, explanation: "GKE gives teams fine-grained control over complex orchestration, networking, and multi-container configurations, whereas Cloud Run trades that control for simplicity and reduced operational overhead." },
  { id: 45, domain: "infrastructure", question: "A media company has video files that are accessed frequently for the first month after upload, then rarely (perhaps once every few months) after that. Which Cloud Storage strategy minimizes cost while keeping access convenient?", options: ["Store everything in Archive storage from day one", "Use Standard storage initially and set an Object Lifecycle Management rule to transition objects to Nearline or Coldline storage after 30 days", "Delete the files after 30 days", "Use only one storage class permanently regardless of access pattern"], answer: 1, explanation: "Object Lifecycle Management can automatically move objects between storage classes based on age or other rules, letting you pay Standard-storage prices only for the period of frequent access." },
  { id: 46, domain: "infrastructure", question: "Which Cloud Storage class is best suited for data that must be retained for compliance for 7 years and will almost never be accessed?", options: ["Standard", "Nearline", "Coldline", "Archive"], answer: 3, explanation: "Archive storage is the lowest-cost, lowest-availability class, designed for data accessed less than once a year, such as long-term compliance archives." },
  { id: 47, domain: "infrastructure", question: "A company wants to store data it expects to access about once a month, such as monthly backup snapshots. Which storage class is the best cost/access tradeoff?", options: ["Standard", "Nearline", "Coldline", "Archive"], answer: 1, explanation: "Nearline storage is designed for data accessed less than once a month, offering a good balance of low storage cost with reasonably quick access when needed." },
  { id: 48, domain: "infrastructure", question: "What best describes \"lift-and-shift\" as a cloud migration strategy?", options: ["Rewriting an application entirely using cloud-native serverless services", "Moving an application to the cloud with minimal or no changes to its architecture", "Deleting the old application and building a brand new one", "Running the application simultaneously on-premises and in the cloud forever"], answer: 1, explanation: "Lift-and-shift (rehosting) moves an application to the cloud largely as-is, which is typically the fastest migration path but captures fewer cloud-native benefits than replatforming or refactoring." },
  { id: 49, domain: "infrastructure", question: "A company migrates its application to the cloud and, without changing its core architecture, switches its database to a managed cloud database service to reduce operational overhead. What is this migration strategy called?", options: ["Lift-and-shift (rehosting)", "Replatforming", "Refactoring", "Retiring"], answer: 1, explanation: "Replatforming involves making some optimizations, such as swapping a self-managed database for a managed cloud service, without changing the application's core architecture." },
  { id: 50, domain: "infrastructure", question: "What is \"refactoring\" (re-architecting) in the context of cloud migration?", options: ["Moving a virtual machine image unchanged to the cloud", "Substantially redesigning an application to take full advantage of cloud-native features, such as breaking a monolith into microservices", "Turning off an application entirely", "Only changing the application's user interface colors"], answer: 1, explanation: "Refactoring involves significant redesign, such as decomposing a monolithic application into microservices, to fully leverage cloud-native scalability and services, typically at higher effort/cost but greater long-term benefit." },
  { id: 51, domain: "infrastructure", question: "Which Google Cloud tool is specifically designed to help migrate on-premises or other-cloud virtual machines into Compute Engine with minimal downtime?", options: ["Migrate to Virtual Machines", "BigQuery", "Cloud CDN", "Cloud Functions"], answer: 0, explanation: "Migrate to Virtual Machines (formerly Velostrata) is designed to move VM workloads from on-premises or other clouds into Compute Engine with minimal downtime and configuration changes." },
  { id: 52, domain: "infrastructure", question: "What is a Virtual Private Cloud (VPC) in Google Cloud?", options: ["A physical data center owned exclusively by one customer", "A private, logically isolated virtual network within Google Cloud where you can deploy resources and control IP ranges, subnets, and firewall rules", "A type of storage bucket", "A billing feature that reduces network costs"], answer: 1, explanation: "A VPC is a private, software-defined network in Google Cloud that lets you define IP address ranges, subnets, routes, and firewall rules to control how your resources communicate." },
  { id: 53, domain: "infrastructure", question: "A global e-commerce company wants to distribute incoming user traffic across multiple backend instances in different regions and automatically route users to the closest healthy backend. Which service should they use?", options: ["Cloud Load Balancing", "Cloud Bigtable", "Cloud Functions", "Migrate to Virtual Machines"], answer: 0, explanation: "Cloud Load Balancing distributes traffic across multiple backends and regions, routing users to the nearest healthy instance to improve performance and availability." },
  { id: 54, domain: "infrastructure", question: "Which Google Cloud service caches content at edge locations around the world to reduce latency for end users accessing static web content like images and videos?", options: ["Cloud CDN", "Cloud Interconnect", "Cloud Spanner", "Cloud Composer"], answer: 0, explanation: "Cloud CDN (Content Delivery Network) caches content at Google's globally distributed edge locations, reducing latency and origin server load for end users." },
  { id: 55, domain: "infrastructure", question: "A large enterprise wants a dedicated, private, high-bandwidth physical connection between its on-premises data center and Google Cloud, rather than routing traffic over the public internet. Which service should it use?", options: ["Cloud Interconnect", "Cloud CDN", "Cloud Functions", "Firestore"], answer: 0, explanation: "Cloud Interconnect provides dedicated, low-latency, high-throughput physical connections between on-premises infrastructure and Google Cloud, avoiding the public internet." },
  { id: 56, domain: "infrastructure", question: "What problem does Anthos primarily help solve for enterprises?", options: ["It provides a single relational database for all data", "It lets organizations manage and run containerized applications consistently across on-premises, Google Cloud, and other public clouds", "It is a billing dashboard for tracking cloud spend", "It is a pre-trained AI API for text analysis"], answer: 1, explanation: "Anthos is a hybrid and multi-cloud platform built on Kubernetes that provides a consistent way to deploy, manage, and secure applications across on-premises data centers and multiple public clouds." },
  { id: 57, domain: "infrastructure", question: "A retailer wants to run Google Cloud services in its own physical store locations and data centers for low-latency, data-residency, or connectivity reasons, using Google-managed hardware. Which offering addresses this?", options: ["Google Distributed Cloud", "Cloud Functions", "BigQuery", "Cloud SQL"], answer: 0, explanation: "Google Distributed Cloud extends Google Cloud infrastructure and services into customer data centers or edge locations, addressing latency, data residency, and connectivity requirements." },
  { id: 58, domain: "infrastructure", question: "Which statement correctly compares Compute Engine and App Engine?", options: ["Compute Engine is a PaaS while App Engine is IaaS", "Compute Engine provides infrastructure-as-a-service (customizable VMs), while App Engine standard is platform-as-a-service (deploy code, platform manages infrastructure)", "They are identical products with different names", "App Engine cannot run web applications"], answer: 1, explanation: "Compute Engine is infrastructure-as-a-service, giving control over VMs and OS, while App Engine standard is platform-as-a-service, abstracting away infrastructure so developers just deploy code." },
  { id: 59, domain: "infrastructure", question: "An organization needs to run a workload that requires no code changes to legacy software, keep full OS-level control, but wants to stop managing physical hardware. Which compute choice best fits?", options: ["Cloud Functions", "Compute Engine", "Cloud Run", "BigQuery"], answer: 1, explanation: "Compute Engine offers VMs with full OS-level control, ideal for legacy workloads being lifted-and-shifted, while still removing the burden of physical hardware management." },
  { id: 60, domain: "infrastructure", question: "What is a key advantage of choosing Cloud Run over building and managing a Kubernetes cluster for a simple stateless web service?", options: ["Cloud Run requires manually patching node operating systems", "Cloud Run abstracts away all cluster and infrastructure management, letting developers focus purely on the container and code", "Cloud Run cannot scale automatically", "Cloud Run does not support HTTPS"], answer: 1, explanation: "Cloud Run removes the operational burden of cluster management (nodes, patching, scaling policy) that GKE requires, letting a developer simply deploy a container and let Google manage the rest." },
  { id: 61, domain: "infrastructure", question: "A company evaluating storage costs learns that retrieving data from Coldline or Archive storage classes involves additional retrieval fees and longer access times compared to Standard. What does this tradeoff illustrate?", options: ["Cheaper storage classes always have unlimited free retrieval", "Google Cloud's storage classes trade lower per-GB storage cost for higher retrieval cost/latency, so class choice should match expected access frequency", "Storage class has no effect on cost", "Archive storage is meant for data accessed daily"], answer: 1, explanation: "Coldline and Archive offer the lowest storage prices but charge more for retrieval and have longer minimum storage durations, making them suitable only for infrequently accessed data." },
  { id: 62, domain: "infrastructure", question: "In a hybrid cloud strategy, what does \"hybrid\" specifically refer to?", options: ["Using two different programming languages in the same app", "Combining on-premises infrastructure with public cloud resources, often integrated to work together", "Using only one cloud vendor exclusively", "Running only mobile applications"], answer: 1, explanation: "A hybrid cloud strategy combines on-premises (or private cloud) infrastructure with public cloud resources, often for gradual migration, regulatory, or latency reasons." },
  { id: 63, domain: "infrastructure", question: "What does a \"multi-cloud\" strategy mean, as distinct from hybrid cloud?", options: ["Using more than one public cloud provider (e.g., Google Cloud and another provider) for different workloads, without necessarily involving on-premises infrastructure", "Running the same virtual machine twice for redundancy", "Using multiple regions within a single cloud provider", "A strategy exclusive to government agencies"], answer: 0, explanation: "Multi-cloud refers to using multiple public cloud providers, potentially for different workloads, resilience, or negotiating leverage, whereas hybrid cloud specifically combines on-premises and public cloud." },
  { id: 64, domain: "infrastructure", question: "A company is choosing a compute option for a REST API backend that experiences unpredictable traffic spikes and needs to scale automatically without any server management, while running as a container. Which two options would both be reasonable candidates?", options: ["Compute Engine and Cloud Interconnect", "Cloud Run and Google Kubernetes Engine", "Cloud CDN and Cloud Storage", "BigQuery and Looker"], answer: 1, explanation: "Cloud Run and GKE (with autoscaling configured) can both run containerized workloads and scale with demand; Cloud Run offers the simplest serverless experience, while GKE gives more configuration control." },
  { id: 65, domain: "infrastructure", question: "What is the primary purpose of firewall rules within a VPC?", options: ["To speed up data transfer between regions", "To control which traffic is allowed or denied to and from resources within the network, based on IP, port, and protocol", "To automatically back up data", "To manage user billing accounts"], answer: 1, explanation: "VPC firewall rules allow or deny traffic to and from resources based on criteria like source/destination IP address, port, and protocol, controlling network access." },
  { id: 66, domain: "infrastructure", question: "A company wants to reduce latency for users in Europe accessing an application hosted primarily in a US region, without duplicating the entire application. Which approach addresses just the static content delivery aspect of this problem?", options: ["Migrate to Virtual Machines", "Cloud CDN to cache and serve static assets from edge locations near European users", "Cloud Spanner", "Cloud Composer"], answer: 1, explanation: "Cloud CDN caches static content at edge locations close to end users, reducing latency for those assets without requiring a full duplicate deployment of the application in another region." },

  // ── SECURITY & OPERATIONS ────────────────────────────────────────────────────
  { id: 67, domain: "security", question: "Under the shared responsibility model, which of the following is Google Cloud always responsible for, regardless of the service model (IaaS, PaaS, SaaS)?", options: ["The customer's application-level access controls", "The security of the underlying physical infrastructure, including data centers, hardware, and the virtualization layer", "The customer's data classification policies", "The customer's choice of IAM roles"], answer: 1, explanation: "In the shared responsibility model, Google is always responsible for securing the physical infrastructure and the layers below whatever service the customer consumes; the customer retains responsibility for aspects like data, access management, and configuration that vary based on the service model." },
  { id: 68, domain: "security", question: "In the shared responsibility model, as a customer moves from IaaS (e.g., Compute Engine) to SaaS (e.g., Google Workspace), what generally happens to the customer's share of the security responsibility?", options: ["It increases significantly", "It decreases, since Google manages more of the stack in SaaS than in IaaS", "It stays exactly the same regardless of service model", "It becomes entirely the customer's responsibility"], answer: 1, explanation: "As you move up the stack from IaaS to PaaS to SaaS, Google manages progressively more layers (OS, runtime, application), so the customer's share of security responsibility decreases correspondingly." },
  { id: 69, domain: "security", question: "What is the purpose of Identity and Access Management (IAM) in Google Cloud?", options: ["To monitor network bandwidth usage", "To control who (identity) has what level of access (roles/permissions) to which resources", "To back up data automatically", "To manage billing invoices only"], answer: 1, explanation: "IAM lets administrators define which identities (users, groups, service accounts) can perform which actions on specific Google Cloud resources, following the principle of least privilege." },
  { id: 70, domain: "security", question: "What distinguishes a \"basic role\" (like Owner, Editor, Viewer) from a \"predefined role\" in Google Cloud IAM?", options: ["Basic roles are extremely broad and grant many permissions across a project, while predefined roles are narrower and scoped to a specific service or task", "Basic roles are more secure than predefined roles", "Predefined roles can only be used by Google support staff", "There is no difference between the two"], answer: 0, explanation: "Basic roles (Owner, Editor, Viewer) are broad, legacy roles granting wide permissions across a project, whereas predefined roles are finer-grained, scoped to specific services, better supporting least-privilege access." },
  { id: 71, domain: "security", question: "A company needs a permission set that doesn't match any existing predefined role exactly, combining a very specific and unusual set of permissions. What should they create?", options: ["A basic Owner role for everyone", "A custom IAM role with exactly the permissions needed", "A Security Command Center alert", "A new Google Cloud organization"], answer: 1, explanation: "Custom roles let administrators define a precise set of permissions tailored to a specific need, when neither basic nor predefined roles fit exactly, supporting least-privilege access." },
  { id: 72, domain: "security", question: "What is the correct order of the Google Cloud resource hierarchy, from broadest to narrowest?", options: ["Project → Folder → Organization → Resource", "Organization → Folder → Project → Resource", "Resource → Project → Organization → Folder", "Folder → Resource → Organization → Project"], answer: 1, explanation: "The Google Cloud resource hierarchy flows from the Organization (top) down through Folders, then Projects, down to individual Resources, with IAM policies inheriting downward." },
  { id: 73, domain: "security", question: "Why does the Google Cloud resource hierarchy (organization, folders, projects) matter for IAM?", options: ["It has no effect on IAM; permissions must be set individually on every resource", "IAM policies set at a higher level (e.g., organization or folder) are inherited by resources beneath them, simplifying access management at scale", "It only affects billing, not access control", "Folders can only exist without an organization"], answer: 1, explanation: "IAM policies applied at the organization or folder level are inherited by all projects and resources beneath them, allowing administrators to manage access consistently across many projects without configuring each one individually." },
  { id: 74, domain: "security", question: "What is Security Command Center used for in Google Cloud?", options: ["Managing billing budgets", "Providing centralized visibility into security posture, detecting vulnerabilities and threats across an organization's Google Cloud assets", "Hosting virtual machines", "Running SQL analytics queries"], answer: 1, explanation: "Security Command Center is a security and risk management platform that provides asset inventory, vulnerability detection, and threat detection across an organization's Google Cloud resources." },
  { id: 75, domain: "security", question: "A compliance officer needs evidence that Google Cloud meets specific industry standards (such as ISO 27001 or SOC 2) before approving a migration. Where would they typically find this information?", options: ["By personally auditing Google's data centers on-site", "Google Cloud's published compliance reports and certifications, available through resources like the Compliance Resource Center", "By asking a competitor", "These certifications do not exist for cloud providers"], answer: 1, explanation: "Google Cloud publishes compliance certifications and audit reports (e.g., ISO 27001, SOC 2/3, PCI DSS) that customers can review to support their own regulatory and compliance requirements." },
  { id: 76, domain: "security", question: "Which service should an operations team use to collect, store, and analyze log data from applications and infrastructure running on Google Cloud?", options: ["Cloud Logging", "Cloud Billing", "Security Command Center", "IAM"], answer: 0, explanation: "Cloud Logging is Google Cloud's service for storing, searching, and analyzing log data generated by applications and infrastructure resources." },
  { id: 77, domain: "security", question: "A team wants to track resource performance metrics, set up dashboards, and receive alerts when a service's error rate or latency crosses a threshold. Which service should they use?", options: ["Cloud Monitoring", "Cloud Storage", "Cloud Interconnect", "Migrate to Virtual Machines"], answer: 0, explanation: "Cloud Monitoring collects metrics, uptime checks, and provides dashboards and alerting policies to notify teams when performance thresholds are breached." },
  { id: 78, domain: "security", question: "How do Cloud Monitoring and Cloud Logging typically work together?", options: ["They are entirely unrelated services with no integration", "Cloud Logging captures detailed log records, while Cloud Monitoring tracks metrics and can alert based on log-based metrics, giving teams both detailed records and real-time operational visibility", "Cloud Monitoring replaces the need for any logging", "Cloud Logging is only used for billing records"], answer: 1, explanation: "Cloud Logging stores detailed event and application logs, while Cloud Monitoring focuses on metrics, dashboards, and alerting; together they give operations teams full observability, and log-based metrics can even feed into Monitoring alerts." },
  { id: 79, domain: "security", question: "A finance manager wants to be automatically notified when monthly Google Cloud spending is on track to exceed a set amount. What should they configure?", options: ["A Security Command Center finding", "A budget with a budget alert in Cloud Billing", "An IAM custom role", "A Cloud Logging sink"], answer: 1, explanation: "Cloud Billing budgets let you set a spending target and configure alert thresholds that notify stakeholders via email or Pub/Sub when actual or forecasted spend approaches or exceeds the budget." },
  { id: 80, domain: "security", question: "Before migrating a workload to Google Cloud, a solutions architect wants to estimate the likely monthly cost of a proposed set of Compute Engine instances, storage, and networking. Which tool should they use?", options: ["Cloud Pricing Calculator", "Security Command Center", "Cloud Composer", "Firestore"], answer: 0, explanation: "The Google Cloud Pricing Calculator lets users estimate the cost of a proposed configuration of resources before deploying them, aiding budgeting and planning." },
  { id: 81, domain: "security", question: "A company wants a detailed breakdown of exactly which projects, services, and SKUs are driving its Google Cloud costs each month. Which capability provides this?", options: ["Cloud Billing reports and cost breakdown/export tools", "IAM audit logs", "Security Command Center vulnerability findings", "Cloud CDN cache statistics"], answer: 0, explanation: "Cloud Billing reports (and billing data exports to BigQuery) let organizations analyze costs by project, service, SKU, and label, supporting detailed cost attribution and optimization." },
  { id: 82, domain: "security", question: "A startup with a small team needs occasional help via email with generally a next-business-day response, and is cost-sensitive. Which type of Google Cloud support tier best fits this need?", options: ["Premium support with a 15-minute critical response SLA", "A basic/standard-tier support plan with slower response times at lower cost", "No support option is available on Google Cloud", "Only enterprise customers can receive any support"], answer: 1, explanation: "Google Cloud offers tiered support plans; lower-cost tiers provide slower response times suited to smaller or less urgent needs, while higher tiers (like Premium/Enhanced) offer faster SLAs for mission-critical production environments." },
  { id: 83, domain: "security", question: "Why might a large enterprise with mission-critical production workloads choose a premium (highest-tier) Google Cloud support plan?", options: ["It is required for using Compute Engine at all", "It provides faster response time SLAs, a designated technical account team, and proactive support for critical business needs", "It is the only tier that includes any documentation access", "It removes the need for internal IT staff entirely"], answer: 1, explanation: "Premium/higher support tiers offer faster guaranteed response times, more direct access to Google support engineers, and sometimes a dedicated technical account manager, valuable for mission-critical workloads." },
  { id: 84, domain: "security", question: "A newly hired employee should be able to view (but not modify) resources in a specific project for their onboarding period. Which IAM approach follows least-privilege best practice?", options: ["Grant them the Owner basic role on the entire organization", "Grant them a predefined Viewer role scoped to that specific project", "Give them the organization administrator role", "Share a shared password with full admin access"], answer: 1, explanation: "Least privilege means granting only the access needed, a Viewer role scoped to the relevant project, rather than broad Owner or organization-wide access." },
  { id: 85, domain: "security", question: "What is a \"service account\" in Google Cloud IAM?", options: ["A human user's personal login credential", "A special type of account used by applications or virtual machines (not a person) to authenticate and make authorized API calls", "A billing account used only for invoicing", "A support ticket account"], answer: 1, explanation: "A service account is a non-human identity used by applications, VMs, or services to authenticate to Google Cloud APIs and access resources programmatically." },
  { id: 86, domain: "security", question: "An organization's security team wants a single place to see misconfigurations, vulnerabilities, and active threats across all projects in their Google Cloud organization. Which service best supports this need?", options: ["Cloud Billing", "Security Command Center", "Cloud Composer", "Data Fusion"], answer: 1, explanation: "Security Command Center aggregates asset inventory, vulnerability findings, and threat detection across an organization's Google Cloud footprint into a centralized dashboard." },
  { id: 87, domain: "security", question: "Which best describes the principle of least privilege as applied through IAM?", options: ["Every user should be granted Owner access by default for convenience", "Users and service accounts should be granted only the minimum permissions necessary to perform their required tasks", "Least privilege means removing all access from all accounts", "Least privilege only applies to Google employees, not customers"], answer: 1, explanation: "The principle of least privilege means granting the smallest set of permissions needed for a task, reducing the risk and impact of compromised credentials or accidental misuse." },
  { id: 88, domain: "security", question: "A company organizes its Google Cloud resources into folders for \"Finance,\" \"Engineering,\" and \"Marketing,\" each containing several projects. What is the main benefit of this folder-based structure?", options: ["Folders improve compute performance", "Folders allow department-level grouping of projects so that IAM policies and organizational policies can be applied consistently to all projects within a department", "Folders reduce the storage cost of all resources within them", "Folders are required before any project can be created"], answer: 1, explanation: "Folders let organizations group related projects (e.g., by department) so that IAM and policy settings applied at the folder level are inherited by every project inside, simplifying governance at scale." },
  { id: 89, domain: "security", question: "What kind of information does an uptime check in Cloud Monitoring provide?", options: ["Whether a service or endpoint is reachable and responding correctly from various locations, on a scheduled basis", "The total monthly bill for a project", "A list of IAM roles granted to a user", "A list of open Security Command Center findings only"], answer: 0, explanation: "Uptime checks in Cloud Monitoring periodically test whether an endpoint (e.g., a website or API) is reachable and responding as expected from multiple global locations, alerting teams to outages." },
  { id: 90, domain: "security", question: "Which action best demonstrates applying the shared responsibility model correctly when using a managed database service like Cloud SQL?", options: ["Assuming Google will configure your application's database access credentials and query logic for you", "Relying on Google to patch and secure the underlying database engine and infrastructure, while the customer configures IAM access, network rules, and manages their own data and application-level security", "Assuming the customer must personally patch the physical server hosting Cloud SQL", "Ignoring IAM entirely since Google handles all security in managed services"], answer: 1, explanation: "With managed services like Cloud SQL, Google handles infrastructure and platform-level security and patching, while the customer remains responsible for configuring access controls, network settings, and securing their own data and application logic." },
  { id: 91, domain: "security", question: "An auditor asks how a company can prove which specific user made a change to a critical Google Cloud resource and when. Which capability directly supports this?", options: ["Cloud Billing reports", "Cloud Audit Logs (part of Cloud Logging)", "The Pricing Calculator", "Cloud CDN cache logs"], answer: 1, explanation: "Cloud Audit Logs record who did what, where, and when across Google Cloud services, providing the accountability trail auditors need to verify administrative and data access actions." },
  { id: 92, domain: "security", question: "A company wants to prevent any team member from accidentally creating resources in regions outside their approved list, regardless of their IAM permissions. What Google Cloud capability is designed for this kind of guardrail?", options: ["Organization Policy Service (org policies)", "Cloud CDN", "BigQuery access controls only", "Cloud Pricing Calculator"], answer: 0, explanation: "The Organization Policy Service lets administrators set organization-wide constraints, such as restricting which regions resources can be created in, that apply regardless of individual IAM grants." },
  { id: 93, domain: "security", question: "Which of the following is an example of a compliance/regulatory consideration a customer might need to evaluate before adopting a cloud provider?", options: ["The number of blog posts the provider has published", "Whether the provider can meet data residency, industry certification (e.g., HIPAA, PCI DSS), or regional legal requirements relevant to the customer's industry", "The color scheme of the provider's admin console", "The provider's stock price"], answer: 1, explanation: "Compliance considerations include whether the cloud provider can satisfy requirements like data residency, industry-specific certifications (e.g., HIPAA for healthcare, PCI DSS for payments), and regional regulations." },
  { id: 94, domain: "security", question: "A team lead notices unexpected cost spikes in the current month and wants both a historical breakdown and a forecast of where costs are headed if the trend continues. Which tool combination should they use?", options: ["Cloud Billing reports for historical breakdown and budgets/forecast alerts for the trend", "Security Command Center only", "Cloud Logging only", "IAM roles only"], answer: 0, explanation: "Cloud Billing reports provide historical cost breakdowns by project/service, while budgets with alerts can notify the team based on actual and forecasted spend trends." },
  { id: 95, domain: "security", question: "Why is it good practice to use groups (rather than granting IAM roles to individual users one by one) when managing access for a large team?", options: ["Groups make it impossible to ever change permissions", "Granting roles to a group lets you manage access for many users at once by adding/removing group membership, simplifying administration and reducing errors", "IAM does not support granting roles to individual users", "Groups bypass the need for any resource hierarchy"], answer: 1, explanation: "Assigning IAM roles to groups rather than individual users lets administrators manage access at scale, simply by adding or removing users from the group, reducing administrative overhead and the chance of misconfiguration." },
];

